/* ============================================================================
 *  IntMap — registrable domain by the Public Suffix List   (js/public-suffix.js)
 * ----------------------------------------------------------------------------
 *  «Is this host on the same site as that one?» cannot be answered from the last two labels: a.co.jp and b.co.jp are two
 *  organisations, a.github.io and b.github.io are two users. The list (js/public-suffix-data.js, generated by
 *  scripts/build-public-suffix.mjs) is the only authority that knows. PURE: no DOM, no network.
 *  Algorithm: https://github.com/publicsuffix/list/wiki/Format#algorithm (an exception rule wins; else the longest match;
 *  else the last label is the suffix).
 * ==========================================================================*/
import { PSL_RULES } from './public-suffix-data.js';

let rules = null;
function load() {
  if (rules) return rules;
  rules = new Set(PSL_RULES.split(' '));
  return rules;
}
const isIp = (h) => /^\d{1,3}(\.\d{1,3}){3}$/.test(h) || h.includes(':');

/** The public suffix of a lower-case ASCII host: 'co.jp' for 'a.b.co.jp'; the host's last label when no rule matches. */
export function publicSuffix(host) {
  const labels = String(host).toLowerCase().replace(/\.$/, '').split('.');
  const set = load();
  let best = 1;                                           /* the implicit «*» rule */
  for (let i = 0; i < labels.length; i++) {
    const tail = labels.slice(i).join('.');
    if (set.has('!' + tail)) return labels.slice(i + 1).join('.');
    if (set.has(tail)) best = Math.max(best, labels.length - i);
    if (i < labels.length - 1 && set.has('*.' + labels.slice(i + 1).join('.'))) best = Math.max(best, labels.length - i);
  }
  return labels.slice(Math.max(0, labels.length - best)).join('.');
}

/** The registrable domain (suffix + one label), or '' when the host IS a public suffix or is an IP literal. */
export function registrableDomain(host) {
  const h = String(host).toLowerCase().replace(/\.$/, '');
  if (!h || isIp(h)) return '';
  const suffix = publicSuffix(h);
  if (h === suffix) return '';
  const labels = h.split('.'), n = suffix.split('.').length;
  return labels.slice(labels.length - n - 1).join('.');
}

/** True when both hosts share a registrable domain; a host with none (an IP, a bare suffix) matches only itself. */
export function sameRegistrableDomain(a, b) {
  const x = String(a).toLowerCase().replace(/\.$/, ''), y = String(b).toLowerCase().replace(/\.$/, '');
  const rx = registrableDomain(x), ry = registrableDomain(y);
  return rx && ry ? rx === ry : x === y;
}
